// Loads the prebuilt content (content/*.json, generated by scripts/build-index.ts).
import type { AsignaturaIndex, ContentIndex, TarjetaIndex, TemaContent } from '../../../shared/types.ts';

const BASE = import.meta.env.BASE_URL;

async function getJson<T>(path: string): Promise<T> {
  const res = await fetch(`${BASE}${path}`);
  if (!res.ok) throw new Error(`No se pudo cargar ${path} (${res.status})`);
  return (await res.json()) as T;
}

let indexP: Promise<ContentIndex> | null = null;
export function loadIndex(): Promise<ContentIndex> {
  indexP ??= getJson<ContentIndex>('content/index.json').catch((e) => {
    indexP = null;
    throw e;
  });
  return indexP;
}

const cardFiles = new Map<string, Promise<TarjetaIndex[]>>();
export function loadSubjectCards(a: AsignaturaIndex): Promise<TarjetaIndex[]> {
  if (!a.tarjetasUrl) return Promise.resolve([]);
  let p = cardFiles.get(a.slug);
  if (!p) {
    p = getJson<TarjetaIndex[]>(a.tarjetasUrl);
    cardFiles.set(a.slug, p);
    p.catch(() => cardFiles.delete(a.slug));
  }
  return p;
}

/** All cards of active subjects (or of every subject when includeArchived). */
export async function loadAllCards(index: ContentIndex, includeArchived = false): Promise<TarjetaIndex[]> {
  const subjects = index.asignaturas.filter((a) => includeArchived || a.estado === 'activa');
  const lists = await Promise.all(subjects.map(loadSubjectCards));
  return lists.flat();
}

const temaFiles = new Map<string, Promise<TemaContent>>();
export function loadTema(url: string): Promise<TemaContent> {
  let p = temaFiles.get(url);
  if (!p) {
    p = getJson<TemaContent>(url);
    temaFiles.set(url, p);
    p.catch(() => temaFiles.delete(url));
  }
  return p;
}

export function findSubject(index: ContentIndex, slug: string): AsignaturaIndex | undefined {
  return index.asignaturas.find((a) => a.slug === slug);
}

/** Next exam (today or later) of a subject, as YYYY-MM-DD. */
export function nextExam(a: AsignaturaIndex, today: string): string | null {
  return a.examenes.map((e) => e.fecha).filter((f) => f >= today).sort()[0] ?? null;
}
